      meaning: "The load balancer had no target to send the request to.",
      causes: ["The target group has no registered targets", "The listener rule points at an empty target group", "The Auto Scaling group is attached to another target group"],
      confirm: ["aws elbv2 describe-listeners --load-balancer-arn <alb-arn>", "aws elbv2 describe-target-health --target-group-arn <tg-arn>"],
      fix: ["Register targets, or attach the Auto Scaling group to the target group"],
